reset role;
select set_config('request.jwt.claim.sub','',true);
create temporary table sp_sources(label text primary key,payload jsonb);
create temporary table sp_problems(label text primary key,payload jsonb);
create temporary table sp_results(label text primary key,payload jsonb);
grant select,insert on sp_sources,sp_problems,sp_results to authenticated;
insert into sp_sources select 'Personal',payload from bc_entries where label='Personal';
insert into sp_sources select 'Team',to_jsonb(b) from public.brainstorm_entries b where id=(select (payload->>'id')::uuid from bc_entries where label='R1');
insert into sp_sources select 'Hidden',payload from bc_entries where label='R3';
insert into sp_problems select label,payload from logged_objects where label in('Problem','Team','Case','Individual Idea');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000006004',true);
insert into sp_problems select 'P2',public.create_development_object((payload->>'id')::uuid,(payload->>'primary_workspace_id')::uuid,'PROBLEM','Second Problem','Original P2',null) from logged_projects where label='Individual';
insert into sp_sources select names.name,public.create_brainstorm_entry((payload #>> '{activity,id}')::uuid,case when names.name='Blank' then '  ' else 'Same human content' end,'private') from bc_activities cross join unnest(array['S2','S3','Blank','IdeaConflict','Rollback1','Rollback2','Rollback3','Rollback4','Rollback5','Race']) as names(name) where bc_activities.label='Personal';
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000006007',true);
insert into sp_problems select 'Team B',public.create_development_object((payload->>'id')::uuid,(payload->>'primary_workspace_id')::uuid,'PROBLEM','B private','B private',null) from logged_projects where label='Brainstorm Team B';
reset role;
create temporary table sp_source_before as select s.label,to_jsonb(b) payload from sp_sources s join public.brainstorm_entries b on b.id=(s.payload->>'id')::uuid;
create temporary table sp_problem_before as select p.label,to_jsonb(o) payload from sp_problems p join public.development_objects o on o.id=(p.payload->>'id')::uuid;
create temporary table sp_artifacts_before as select jsonb_build_object('artifacts',(select jsonb_agg(to_jsonb(x) order by id) from public.artifacts x),'versions',(select jsonb_agg(to_jsonb(x) order by id) from public.artifact_versions x),'links',(select jsonb_agg(to_jsonb(x) order by id) from public.artifact_object_links x)) payload;
create function pg_temp.sp_entry(label0 text) returns uuid language sql as $$select (payload->>'id')::uuid from sp_sources where label=label0$$;
create function pg_temp.sp_problem(label0 text) returns uuid language sql as $$select (payload->>'id')::uuid from sp_problems where label=label0$$;
